  "Insects visited after the flowers opened.": "d2e1ff89646ce48f451b.mp3",
  "Leave wild animals enough space.": "ca2f437cdcc432897cb7.mp3",
  "The park path takes five more minutes.": "281096056878dcb5d7a8.mp3",
  "Our observations changed with the seasons.": "3bd30f37df74bd20f1d9.mp3",
  "A fence protects the young plants.": "6a8f35d5c85398c015b1.mp3",
  "We counted visitors without touching them.": "5c810be1fda6a90517ef.mp3",
  "A class wants to make its school yard greener, but there is little spare space.": "a05ba0dc1c752a196025.mp3",
  "The children ask permission to place three pots near a fence.": "c9aaf422dddf637b2593.mp3",
